/**
 * add-px-phase.js — Add a PX phase (id=-1) to Tickets.json
 *
 * PX is a special phase that stores "tickets that precede P0 / do not belong to
 * any formulated phase". Unlike normal phases generated by formulate-tickets
 * (P0, P1, ...), it is fixed at id=-1 and always inserted at the beginning of the array.
 *
 * Usage:
 *   node add-px-phase.js <PATH to Tickets.json>
 *
 * Exits with an error if the PX phase already exists (prevents duplicates).
 * Schema validation is performed before writing; no save occurs on failure.
 */

const fs = require("fs");
const path = require("path");
const { validateTickets } = require("../lib/validate-tickets");

function main() {
  const jp = process.argv[2];
  if (!jp) {
    console.log(
      JSON.stringify({
        success: false,
        error: "Usage: node add-px-phase.js <PATH to Tickets.json>",
      }),
    );
    process.exit(1);
  }

  const rp = path.resolve(jp);
  let data;
  try {
    data = JSON.parse(fs.readFileSync(rp, "utf8"));
  } catch (e) {
    console.log(
      JSON.stringify({ success: false, error: "Failed to read/parse " + rp }),
    );
    process.exit(1);
  }

  // Duplicate check: whether a phase with id=-1 already exists
  const existing = (data.phases || []).find(function (p) {
    return p.id === -1;
  });
  if (existing) {
    console.log(
      JSON.stringify({
        success: false,
        error: "PX phase (id=-1) already exists",
      }),
    );
    process.exit(1);
  }

  // Create PX phase and insert at the beginning
  // PX-92: Added phaseId and status to ensure schema completeness.
  // Details: `node .claude/scripts/tickets/show-ticket-context.js --ticket-key=PX-92 --for-spec --no-implementation-order`
  const pxPhase = {
    id: -1,
    phaseId: -1,
    status: 'draft',
    name: "[X] 独立フェーズ（P0 に先行／独立）",
    characteristics:
      "P0より前、またはP0以降のどのフェーズにも属さない独立したチケットを格納する特別なフェーズ。",
    tickets: [],
  };
  data.phases.unshift(pxPhase);

  // Schema validation
  const vr = validateTickets(data);
  if (!vr.valid) {
    data.phases.shift(); // Rollback
    console.log(
      JSON.stringify({
        success: false,
        error: "Schema validation failed",
        errors: vr.errors,
      }),
    );
    process.exit(1);
  }

  // Write file
  fs.writeFileSync(rp, JSON.stringify(data, null, 2) + "\n", "utf8");
  console.log(
    JSON.stringify({ success: true, phaseId: -1, name: pxPhase.name }),
  );
}

if (require.main === module) main();
module.exports = { main };
